import os, hashlib, base64, csv, glob
sp = os.path.abspath('site-packages')
for di in sorted(glob.glob(os.path.join(sp,'*.dist-info'))):
    rec = os.path.join(di,'RECORD')
    name = os.path.basename(di)
    issues=[]
    listed=set()
    with open(rec) as f:
        for row in csv.reader(f):
            if not row: continue
            path, h, size = (row+['',''])[:3]
            full = os.path.normpath(os.path.join(sp, path))
            listed.add(full)
            if not os.path.exists(full):
                issues.append(f'MISSING {path}'); continue
            if not h:
                if path.endswith('RECORD'): continue
                issues.append(f'NOHASH {path}'); continue
            alg, val = h.split('=',1)
            d = hashlib.new(alg, open(full,'rb').read()).digest()
            got = base64.urlsafe_b64encode(d).rstrip(b'=').decode()
            if got != val:
                issues.append(f'HASH-MISMATCH {path}')
            else:
                st = os.path.getsize(full)
                if size and int(size)!=st:
                    issues.append(f'SIZE {path}')
    # find files on disk belonging to top_level not in RECORD
    tl = os.path.join(di,'top_level.txt')
    if os.path.exists(tl):
        for mod in open(tl).read().split():
            for cand in [os.path.join(sp,mod), os.path.join(sp,mod+'.py')]:
                if os.path.isdir(cand):
                    for root,_,fs in os.walk(cand):
                        for fn in fs:
                            p=os.path.normpath(os.path.join(root,fn))
                            if p not in listed: issues.append(f'UNRECORDED {os.path.relpath(p,sp)}')
                elif os.path.isfile(cand):
                    if os.path.normpath(cand) not in listed: issues.append(f'UNRECORDED {os.path.relpath(cand,sp)}')
    print(('OK   ' if not issues else 'BAD  ')+name, '' if not issues else issues)
EOF

