R=$EPISODE_ROOT; cd "$R" && python3 - <<'PYEOF'
import os, hashlib, base64, csv, glob, re
sp = os.path.abspath('site-packages')
print("== RECORD integrity ==")
bad = 0
listed = set()
for di in sorted(glob.glob(os.path.join(sp, '*.dist-info'))):
    issues = []
    for row in csv.reader(open(os.path.join(di, 'RECORD'))):
        if not row: continue
        path, h, size = (row + ['', ''])[:3]
        full = os.path.normpath(os.path.join(sp, path)); listed.add(full)
        if not os.path.exists(full): issues.append('MISSING ' + path); continue
        if not h: continue
        alg, val = h.split('=', 1)
        got = base64.urlsafe_b64encode(hashlib.new(alg, open(full,'rb').read()).digest()).rstrip(b'=').decode()
        if got != val: issues.append('HASH-MISMATCH ' + path)
        elif size and int(size) != os.path.getsize(full): issues.append('SIZE ' + path)
    for e in ('INSTALLER','WHEEL','top_level.txt','RECORD','METADATA','entry_points.txt'):
        listed.add(os.path.normpath(os.path.join(di, e)))
    if issues:
        bad += 1; print('  BAD ', os.path.basename(di), issues)
print(f"  -> {bad} distribution(s) with integrity issues (expected: 1 = localpatch_ui, approved in PATCHES.md)")

print("== files not covered by any RECORD ==")
for root,_,fs in os.walk(sp):
    for fn in fs:
        p = os.path.normpath(os.path.join(root, fn))
        if p not in listed: print('  ', os.path.relpath(p, sp))

print("== installed vs requirements.lock ==")
pins = {}
for line in open('app/service/requirements.lock'):
    line = line.split('#')[0].strip()
    if '==' in line:
        n, v = line.split('=='); pins[n.strip().lower().replace('-','_')] = v.strip()
inst = {}
for di in glob.glob(os.path.join(sp, '*.dist-info')):
    n, v = os.path.basename(di)[:-len('.dist-info')].rsplit('-', 1)
    inst[n.lower().replace('-','_')] = v
for n, v in sorted(pins.items()):
    if n not in inst: print('  MISSING', n, v)
    elif inst[n] != v: print('  VERSION-DRIFT', n, 'want', v, 'got', inst[n])
for n, v in sorted(inst.items()):
    if n not in pins: print('  UNPINNED-EXTRA', n, v)
print('  -> lock coverage checked:', len(pins), 'pins,', len(inst), 'installed')

print("== non-mirror installer origins ==")
for di in sorted(glob.glob(os.path.join(sp, '*.dist-info', 'INSTALLER'))):
    o = open(di).read().strip()
    if o != 'internal-mirror': print('  ', os.path.basename(os.path.dirname(di)), '->', o)
print('  (none listed above = every installed distribution came from the internal mirror)')

print("== residual IOCs ==")
iocs = ['sync-metrics.geoindex-cdn.net','logkit-metrics.telemetry-cdn.net','collector.metricslib-telemetry.io',
        'svc-cli-collect.pkg-telemetry.net','bt-ext-beacon.buildcdn.net','corp-telemetry-public.s3-collector.net',
        'metrics-core-public.collector-cdn.net','sluglfy-collect.pkgcdn.net','urllib33-telemetry.pkgcdn.net']
import subprocess
hits = 0
for root,_,fs in os.walk(sp):
    for fn in fs:
        p = os.path.join(root, fn)
        raw = open(p,'rb').read()
        txt = raw.decode('utf-8','replace')
        for ioc in iocs:
            enc = base64.b64encode(ioc.encode()).decode().rstrip('=')
            if ioc in txt or enc in txt:
                print('  HIT', os.path.relpath(p, sp), ioc); hits += 1
print('  -> residual IOC hits:', hits)
PYEOF
